### 2.3 ‑ `src/models/index.ts`

Sets up Sequelize connection and imports all models.

```ts
import { Sequelize } from 'sequelize';
import dotenv from 'dotenv';

dotenv.config();

const sequelize = new Sequelize(
  process.env.DB_NAME!,
  process.env.DB_USER!,
  process.env.DB_PASS!,
  {
    host: process.env.DB_HOST,
    port: Number(process.env.DB_PORT),
    dialect: 'postgres',
    logging: false,
  }
);

export const initModels = () => {
  import('./vehicle').then(m => m.default(sequelize));
  import('./driver').then(m => m.default(sequelize));
  import('./shipment').then(m => m.default(sequelize));

  // Associations
  const { Vehicle } = require('./vehicle');
  const { Driver } = require('./driver');
  const { Shipment } = require('./shipment');

  Vehicle.hasMany(Shipment);
  Shipment.belongsTo(Vehicle);

  Driver.hasMany(Shipment);
  Shipment.belongsTo(Driver);
};

export default sequelize;
```

#### Example Model – `Vehicle`

```ts
// src/models/vehicle.ts
import { DataTypes, Model, Optional, Sequelize } from 'sequelize';

interface VehicleAttributes {
  id: number;
  licensePlate: string;
  make: string;
  model: string;
  year: number;
  capacityTons: number;
}

interface VehicleCreationAttrs extends Optional<VehicleAttributes, 'id'> {}

class Vehicle extends Model<
  VehicleAttributes,
  VehicleCreationAttrs
> implements VehicleAttributes {
  public id!: number;
  public licensePlate!: string;
  public make!: string;
  public model!: string;
  public year!: number;
  public capacityTons!: number;
}

export default (sequelize: Sequelize) => {
  Vehicle.init(
    {
      id: {
        type: DataTypes.INTEGER.UNSIGNED,
        autoIncrement: true,
        primaryKey: true,
      },
      licensePlate: {
        type: DataTypes.STRING(15),
        allowNull: false,
        unique: true,
      },
      make: DataTypes.STRING,
      model: DataTypes.STRING,
      year: DataTypes.SMALLINT,
      capacityTons: DataTypes.FLOAT,
    },
    {
      tableName: 'vehicles',
      sequelize,
    }
  );
};
```

Create similar models for `Driver`, `Shipment`, etc.

### 2.4 ‑ Middleware – Auth

```ts
// src/middleware/auth.ts
import jwt from 'jsonwebtoken';
import { Request, Response, NextFunction } from 'express';
import dotenv from 'dotenv';

dotenv.config();
const secret = process.env.JWT_SECRET!;

export interface JwtPayload {
  sub: string; // userId
  role: string;
}

export const authenticate =
  (req: Request, res: Response, next: NextFunction) =>
  async (err: Error | undefined) => {
    if (!req.headers.authorization)
      return res.status(401).send({ error: 'Missing Authorization Header' });

    try {
      const [, token] = req.headers.authorization.split(' ');
      const payload = jwt.verify(token, secret) as JwtPayload;
      (req as any).payload = payload;
      next(err);
    } catch (_) {
      res.sendStatus(403); // invalid token
    }
  };
```

### 2.5 ‑ Controllers & Routes

Example: `routes/shipment.ts`

```ts
import express from 'express';
import { ShipmentController } from '../controllers/shipment';
import { authenticate } from '../middleware/auth';

const router = express.Router();

// All shipment routes protected
router.use(authenticate);

// Create shipment
router.post('/', ShipmentController.create);
// List shipments
router.get('/', ShipmentController.list);
// Get single
router.get('/:id', ShipmentController.retrieve);
// Update
router.put('/:id', ShipmentController.update);
// Delete
router.delete('/:id', ShipmentController.destroy);

export default router;
```

And controller logic:

```ts
// src/controllers/shipment.ts
import { Request, Response } from 'express';
import { Shipment } from '../models/shipment'; // exported from models/init

export class ShipmentController {
  static create(req: Request, res: Response) {
    const { vehicleId, driverId, origin, destination, weightKg } = req.body;
    return Shipment.create({
      vehicleId,
      driverId,
      origin,
      destination,
      weightKg,
    })
      .then((shp) => res.status(201).json(shp))
      .catch(() => res.status(500).json({ msg: 'Error creating shipment' }));
  }

  static list(_req: Request, res: Response) {
    return Shipment.findAll()
      .then((list) => res.json(list))
      .catch(() => res.status(500).json({ msg: 'Server error' }));
  }

  /* ...retrieve/update/delete... */
}
```

### 2.6 ‑ Server bootstrap

```ts
// src/index.ts
import express from 'express';
import cors from 'cors';
import helmet from 'helmet';
import swaggerUi from 'swagger-ui-express';
import yaml from 'yamljs';
import path from 'path';
import dotenv from 'dotenv';
import sequelize from './models';
import { initModels } from './models';
import shipmentRoutes from './routes/shipment';
// … other route imports …

dotenv.config();

initModels(); // load associations

(async () => {
  await sequelize.authenticate();
  console.log('Database connected.');
  await sequelize.sync({ alter: true }); // dev only
})().catch(console.error);

const app = express();

app.use(cors());
app.use(helmet());
app.use(express.json());

app.use('/api/v1/shipments', shipmentRoutes);
// add other routers here...

// Swagger docs
const specPath = path.join(__dirname, '..', 'docs/swagger.yaml');
const swaggerDocument = yaml.load(specPath);
app.use('/api-docs', swaggerUi.serve, swaggerUi.setup(swaggerDocument));

// Health check
app.get('/healthz', (_, res) => res.send('OK'));

const PORT = process.env.PORT || 4000;
app.listen(PORT, () => console.log(`🚚 TMS API listening on ${PORT}`));
```

Add a basic `swagger.yaml` describing the endpoints—this will automatically generate interactive docs at `/api-docs`.

