```

### 3.2 ‑ Folder tree

```
src/
├─ api/          # Axios wrappers
├─ app/          # Root component + Router
├─ assets/
├─ components/   # Reusable widgets
├─ pages/        # Page-level views
└─ store/        # RTK query slices
```

### 3.3 ‑ API wrapper

```tsx
// src/api/client.ts
import axios from 'axios';

const baseURL = import.meta.env.VITE_API_URL ?? '/api/v1';

export const apiClient = axios.create({
  baseURL,
});

export const setAuthToken = (token: string) => {
  apiClient.defaults.headers.common.Authorization = `Bearer ${token}`;
};
```

### 3.4 ‑ Store slice (RTK Query)

```ts
// src/store/slices/shipmentsSlice.ts
import { createApi, fetchBaseQuery } from '@reduxjs/toolkit/query/react';

export const shipmentsAPI = createApi({
  reducerPath: 'shipmentsAPI',
  baseQuery: fetchBaseQuery({ baseUrl: '/api/v1/' }),
  tagTypes: ['Shipments'],
  endpoints: (builder) => ({
    getShipments: builder.query<any, void>({
      query: () => 'shipments',
      providesTags: ['Shipments'],
    }),

    createShipment: builder.mutation<void, Partial<any>>({
      query: (body) => ({ url: 'shipments', method: 'POST', body }),
      invalidatesTags: ['Shipments'],
    }),

    deleteShipment: builder.mutation<void, number>({
      query(id) {
        return { url: `shipments/${id}`, method: 'DELETE' };
      },
      invalidatesTags: ['Shipments'],
    }),
  }),
});

export const {
  useGetShipmentsQuery,
  useCreateShipmentMutation,
  useDeleteShipmentMutation,
} = shipmentsAPI;
```

### 3.5 ‑ Main App

```tsx
// src/app/App.tsx
import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { CssBaseline, Container } from '@mui/material';
import Navbar from '@/components/Navbar';
import HomePage from '@/pages/HomePage';
import ShipmentsPage from '@/pages/ShipmentsPage';
import LoginPage from '@/pages/LoginPage';

function App() {
  return (
    <>
      <CssBaseline />
      <Navbar />
      <Container sx={{ mt: 4 }}>
        <Router>
          <Routes>
            <Route path="/" element={<HomePage />} />
            <Route path="/login" element={<LoginPage />} />
            <Route path="/shipments" element={<ShipmentsPage />} />
          </Routes>
        </Router>
      </Container>
    </>
  );
}

export default App;
```

### 3.6 ‑ Sample page – Shipments

```tsx
// src/pages/ShipmentsPage.tsx
import React, { useState } from 'react';
import {
  Box,
  Button,
  Dialog,
  TextField,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material';
import {
  useGetShipmentsQuery,
  useCreateShipmentMutation,
  useDeleteShipmentMutation,
} from '@/store/slices/shipmentsSlice';

export default function ShipmentsPage() {
  const { data: shipments, refetch } = useGetShipmentsQuery();
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({});
  const [createShipment] = useCreateShipmentMutation();
  const [deleteShipment] = useDeleteShipmentMutation();

  const handleSubmit = async () => {
    await createShipment(form);
    setOpen(false);
    refetch();
  };

  return (
    <Box>
      <Typography variant="h4">Shipments</Typography>

      <Button
        variant="contained"
        color="primary"
        sx={{ my: 2 }}
        onClick={() => setOpen(true)}
      >
        New Shipment
      </Button>

      {/* Table */}
      <Table size="small">
        <TableHead>
          <TableRow>
            <TableCell>ID</TableCell>
            <TableCell>Origin</TableCell>
            <TableCell>Destination</TableCell>
            <TableCell>Weight&nbsp;(kg)</TableCell>
            <TableCell align="right">Actions</TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {(shipments ?? []).map((s: any) => (
            <TableRow key={s.id}>
              <TableCell>{s.id}</TableCell>
              <TableCell>{s.origin}</TableCell>
              <TableCell>{s.destination}</TableCell>
              <TableCell>{s.weightKg}</TableCell>
              <TableCell align="right">
                <Button
                  color="error"
                  onClick={async () => {
                    await deleteShipment(s.id);
                    refetch();
                  }}
                >
                  X
                </Button>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>

      {/* Modal form */}
      <Dialog open={open} onClose={() => setOpen(false)}>
        <Box p={3} width={350}>
          <TextField
            label="License Plate"
            fullWidth
            margin="normal"
            onChange={(e) =>
              setForm({ ...form, vehicleId: e.target.value.trim() })
            }
          />

          <TextField
            label="Origin"
            fullWidth
            margin="normal"
            onChange={(e) =>
              setForm({ ...form, origin: e.target.value.trim() })
            }
          />

          <TextField
            label="Destination"
            fullWidth
            margin="normal"
            onChange={(e) =>
              setForm({ ...form, destination: e.target.value.trim() })
            }
          />

          <TextField
            label="Weight (kg)"
            type="number"
            fullWidth
            margin="normal"
            onChange={(e) =>
              setForm({ ...form, weightKg: parseFloat(e.target.value) })
            }
          />

          <Button
            variant="contained"
            color="primary"
            sx={{ mt: 2 }}
            onClick={handleSubmit}
          >
            Save
          </Button>
        </Box>
      </Dialog>
    </Box>
  );
}
```

*(Feel free to replace the modal with MUI’s `<Modal>` or a custom dialog.)*

### 3.7 ‑ Map View (optional)

Use **Leaflet** to display current truck positions. Install packages:

```bash
npm i leaflet @leaflet/react-leaflet
```

Then embed a map component showing markers fetched from `/api/v1/trucks`.  

